// One run can bring several new emails. Each one is matched to your leads by the sender's address,
// and carries what the next nodes need, so nothing below depends on the trigger's own shape.
const leads = $('Get all leads').all().map((i) => i.json).filter((r) => r && r.id);
const byEmail = new Map(leads.map((r) => [String(r.email || '').trim().toLowerCase(), r]));
return $('A new email arrives').all().map((i) => {
  const m = i.json;
  const fromAddress = String(m.from?.value?.[0]?.address || '').trim().toLowerCase();
  const lead = byEmail.get(fromAddress) || null;
  return { json: {
    messageId: m.id, threadId: m.threadId,
    from: m.from?.text || fromAddress, fromAddress,
    subject: m.subject || '(no subject)',
    text: String(m.text || m.snippet || '').trim().slice(0, 4000),
    isLead: Boolean(lead), leadId: lead ? lead.id : null,
    leadName: lead ? String(lead.name || '') : '', leadNotes: lead ? String(lead.notes || '').slice(0, 600) : '',
  }, pairedItem: { item: 0 } };
});

