// The model is asked for JSON. This node does not trust it: it parses safely and sends anything
// doubtful to the owner instead of suggesting a reply.
const email = $('Match each email to a lead').item.json;
const s = $('Your settings').first().json;
const raw = String($json.text ?? $json.output ?? '').trim();
let parsed = null;
try {
  parsed = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  parsed = null;
}
const reasons = [];
if (!parsed || typeof parsed !== 'object') reasons.push('the model did not answer in the agreed format');
const categories = ['question', 'booking', 'complaint', 'money', 'other'];
const category = categories.includes(parsed?.category) ? parsed.category : 'other';
const draft = typeof parsed?.draft === 'string' ? parsed.draft.trim() : '';
if (parsed?.needs_person === true) reasons.push('the model asked for a person: ' + String(parsed.reason || 'no reason given'));
if (category === 'money' || category === 'complaint') reasons.push('the email is about ' + category);
if (!draft) reasons.push('the draft is empty');
const maxWords = Number(s.maxReplyWords || 150);
if (draft.split(/\s+/).filter(Boolean).length > maxWords) reasons.push('the draft is longer than ' + maxWords + ' words');
// A price, amount or percentage in the draft must also appear in your business facts.
const facts = String(s.businessFacts || '');
const money = /(?:[$\u20ac\u00a3\u00a5\u20b9]|\b(?:USD|EUR|GBP|AED|BRL|CAD|AUD)\b)\s?\d[\d.,]*|\d[\d.,]*\s?(?:[$\u20ac\u00a3\u00a5\u20b9%]|\b(?:USD|EUR|GBP|AED|BRL|CAD|AUD|dollars?|euros?|pounds?)\b)/gi;
const unknown = (draft.match(money) || []).filter((m) => !facts.includes(m.replace(/[^\d.,]/g, '')));
if (unknown.length) reasons.push('the draft mentions an amount that is not in your facts: ' + unknown.join(', '));
const esc = (t) => String(t || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]).replace(/\n/g, '<br>');
const from = email.from;
const subject = email.subject || '(no subject)';
const original = email.text;
const approvalHtml = '<p><b>From:</b> ' + esc(from) + '<br><b>Subject:</b> ' + esc(subject) + '<br><b>Category:</b> ' + esc(category) + '</p>'
  + (email.isLead ? '<p><b>This sender is one of your leads.</b> Notes: ' + esc(email.leadNotes || '-') + '</p>' : '')
  + '<p><b>Their email</b><br>' + esc(original) + '</p>'
  + '<p><b>Suggested reply</b><br>' + esc(draft) + '</p>'
  + '<p>Nothing has been sent. Approve to send this reply in the same thread, or decline to leave it for you.</p>';
return { json: { messageId: email.messageId, threadId: email.threadId, isLead: email.isLead, leadId: email.leadId, from, subject, original, category, draft, safe: reasons.length === 0, reason: reasons.join('; ') || String(parsed?.reason || ''), approvalHtml } };

