// A lead is quiet when the last contact is older than quietDays, they never replied,
// never unsubscribed, and were never followed up by this workflow. Oldest first, capped at maxPerWeek.
const s = $('Your settings').first().json;
const cutoff = Date.now() - Number(s.quietDays || 30) * 86400000;
const cap = Math.max(0, Number(s.maxPerWeek || 20));
const yes = (v) => v === true || ['true', 'yes', '1'].includes(String(v ?? '').trim().toLowerCase());
const time = (v) => (v ? new Date(v).getTime() : NaN);
const quiet = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.id && /.+@.+\..+/.test(String(r.email || '').trim()))
  .filter((r) => !yes(r.replied) && !yes(r.unsubscribed) && !r.followed_up_at)
  .filter((r) => time(r.last_contact_at) < cutoff)
  .sort((a, b) => time(a.last_contact_at) - time(b.last_contact_at))
  .slice(0, cap);
return quiet.map((r) => ({ json: {
  id: r.id,
  email: String(r.email).trim().toLowerCase(),
  name: String(r.name || '').trim(),
  notes: String(r.notes || '').trim().slice(0, 600),
  last_contact_at: r.last_contact_at,
} }));

// One Gmail search covered every quiet lead. A lead replied if a message from their address
// arrived after their last contact. Every lead comes out once, with repliedInGmail true or false.
const leads = $('Keep only quiet leads').all().map((i) => i.json);
const messages = $input.all().map((i) => i.json).filter((m) => m && m.id);
const address = (v) => (String(v || '').match(/[^\s<>"]+@[^\s<>"]+/) || [''])[0].toLowerCase();
return leads.map((lead) => {
  const since = new Date(lead.last_contact_at).getTime();
  const reply = messages.find((m) => address(m.From) === lead.email && Number(m.internalDate) > since);
  return { json: { ...lead, repliedInGmail: Boolean(reply) }, pairedItem: { item: 0 } };
});

