// Never trust the model's text alone. If any check fails, the fixed text below is used instead,
// and the owner's summary says why. Edit the fixed text to your own words.
const s = $('Your settings').first().json;
const lead = $('Who wrote back').item.json;
const first = lead.name ? lead.name.split(/\s+/)[0] : '';
const text = String($json.text || '').trim();
const words = text.split(/\s+/).filter(Boolean).length;
const problems = [];
if (words < 25 || words > Number(s.maxFollowUpWords || 110) + 10) problems.push('length');
if (/https?:\/\/|www\.|\.com\b/i.test(text)) problems.push('link');
if (/\d/.test(text)) problems.push('number');
if (/[\[\]{}]/.test(text)) problems.push('placeholder');
if (/\b(guarantee|discount|promise)\w*/i.test(text)) problems.push('promise');
if (first && !text.toLowerCase().includes(first.toLowerCase())) problems.push('name');
const fixed = [
  first ? 'Hi ' + first + ',' : 'Hi,',
  '',
  'It has been a while since we last spoke, and I did not want to leave things hanging.',
  '',
  'Is it worth a short conversation now, or should I close the file on my side?',
].join('\n');
const body = (problems.length ? fixed : text) + '\n\n' + s.senderName + '\n' + s.companyName;
return { json: {
  id: lead.id, email: lead.email, name: lead.name, subject: s.followUpSubject, body,
  writtenBy: problems.length ? 'fixed text (' + problems.join(', ') + ')' : 'model',
} };

